#include <iostream>
using namespace std;

using LL = long long;

const LL MOD = 1000000007;

void multiply(const LL a[3], const LL b[3], LL result[3]) {
    LL temp[3] = {0, 0, 0};

    for (int i = 0; i < 3; ++i)
        for (int j = 0; j < 3; ++j)
            temp[(i + j) % 3] =
                (temp[(i + j) % 3] + a[i] * b[j]) % MOD;

    for (int i = 0; i < 3; ++i)
        result[i] = temp[i];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    LL N, L, R;
    cin >> N >> L >> R;

    LL count[3] = {0, 0, 0};
    LL length = R - L + 1;

    for (int i = 0; i < 3; ++i)
        count[i] = (length / 3) % MOD;

    LL remainder = length % 3;
    int firstResidue = static_cast<int>((L % 3 + 3) % 3);

    for (LL i = 0; i < remainder; ++i)
        ++count[(firstResidue + i) % 3];

    LL result[3] = {1, 0, 0};
    LL base[3] = {count[0], count[1], count[2]};

    while (N > 0) {
        if (N & 1)
            multiply(result, base, result);

        multiply(base, base, base);
        N >>= 1;
    }

    cout << result[0] % MOD;
    return 0;
}

