#include <iostream>
#include <array>
using namespace std;

using LL = long long;

const LL MOD = 1000000007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    LL N, L, R;
    cin >> N >> L >> R;

    array<LL, 3> count{};
    for (LL x = L; x <= R && x < L + 3; ++x) {
        count[x % 3] = (R - x) / 3 + 1;
    }

    array<LL, 3> dp{1, 0, 0};

    for (LL i = 0; i < N; ++i) {
        array<LL, 3> next{};
        for (int a = 0; a < 3; ++a) {
            for (int b = 0; b < 3; ++b) {
                next[(a + b) % 3] =
                    (next[(a + b) % 3] + dp[a] * count[b]) % MOD;
            }
        }
        dp = next;
    }

    cout << dp[0] << '\n';
    return 0;
}

